        FROM user a
        WHERE 1=1
        AND userdelNy = 0
        AND useruseNy = 1
        AND a.useruseNy = #{shUseNy}
        AND a.userdelNy = #{shDelNy}


					AND a.userdb BETWEEN #{shDateStartDB} AND #{shDateEndDB}

					AND a.userredb BETWEEN #{shDateStartDB} AND #{shDateEndDB}


            AND a.userseq = #{shValue}
            AND a.username LIKE CONCAT('%',#{shValue},'%')
            AND a.userphonenumber LIKE CONCAT('%',#{shValue},'%')
            AND a.userfirstaddress LIKE CONCAT('%',#{shValue},'%')
